#!/usr/bin/env python3
"""Offline, standard-library-only message compiler. Generated files are committed.

Run `python3 scripts/i18n.py generate [--check]` or `lint [--update-baseline]`.
The deliberately small format supports named parameters and one plural/select
per message; nested selectors, HTML and printf in source text are rejected.
"""
import argparse
import json
from pathlib import Path
import re
import sys
import tempfile
from xml.sax.saxutils import escape

ROOT = Path(__file__).resolve().parents[1]
HEADER = 'Generated by scripts/i18n.py; DO NOT EDIT.'
PLATFORMS = {'web', 'android', 'ios', 'go'}
PARAM = re.compile(r'\{([a-z][a-zA-Z0-9]*)\}')
KEY = re.compile(r'[a-z][a-z0-9_]*(?:\.[a-z][a-z0-9_]*)+')
TYPES = {'string': ('string', 'String', 'String', 'string', '@'),
         'integer': ('number', 'Int', 'Int', 'int', 'lld'),
         'number': ('number', 'Double', 'Double', 'float64', 'g')}


def fail(message):
    raise ValueError(message)


def pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            fail(f'duplicate JSON field: {key}')
        result[key] = value
    return result


def read(path):
    return json.loads(path.read_text(encoding='utf-8'), object_pairs_hook=pairs, parse_constant=lambda value: fail(f'invalid JSON constant: {value}'))


def dump(value):
    return json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + '\n'


def symbol(key):
    return key.replace('.', '_')


def method(key):
    words = symbol(key).split('_')
    return words[0] + ''.join(w.title() for w in words[1:])


def leaves(value):
    return value['forms'].values() if isinstance(value, dict) else [value]


def load(root):
    locales = read(root / 'i18n/locales.json')
    if set(locales) != {'default', 'source', 'selectionEnabled', 'locales'} or type(locales['selectionEnabled']) is not bool:
        fail('invalid locales metadata')
    ids = [l['id'] for l in locales['locales']]
    if locales['default'] != 'zh-CN' or locales['source'] != 'zh-CN':
        fail('the source and fallback contract is zh-CN')
    language_names = [name for loc in locales['locales'] for name in loc['languages']]
    if len(set(language_names)) != len(language_names) or any(not re.fullmatch('[a-z]{2,3}', name) for name in language_names):
        fail('duplicate or invalid language match')
    if len(set(ids)) != len(ids) or locales['default'] not in ids or locales['source'] not in ids:
        fail('invalid locale IDs/default/source')
    for field in ('android', 'apple'):
        if len({l[field] for l in locales['locales']}) != len(ids):
            fail(f'locale {field} collision')
    for loc in locales['locales']:
        if set(loc) != {'id', 'name', 'languages', 'android', 'apple', 'plural'} or not loc['languages']:
            fail('invalid locale fields')
        integers = [i for rule in loc['plural'].values() for i in rule.get('integers', [])]
        if len(set(integers)) != len(integers): fail('overlapping plural rules')
        if 'other' not in loc['plural'] or any(k not in {'zero', 'one', 'two', 'few', 'many', 'other'} for k in loc['plural']):
            fail('invalid plural categories')
        for category, rule in loc['plural'].items():
            if category == 'other' and rule != {} or category != 'other' and (set(rule) != {'integers'} or not all(type(i) is int and i >= 0 for i in rule['integers'])):
                fail('only finite integer plural rules are supported; extend compiler before adding other rules')
    messages, names, methods = {}, set(), set()
    for path in sorted((root / 'i18n/messages').glob('*.json')):
        rows = read(path)
        if not isinstance(rows, list):
            fail(f'{path.name}: expected message array')
        for row in rows:
            key = row['key']
            if not KEY.fullmatch(key) or key.split('.')[0] != path.stem:
                fail(f'invalid/domain-mismatched key: {key}')
            if key in messages:
                fail(f'duplicate key: {key}')
            if symbol(key) in names or method(key) in methods:
                fail(f'platform key collision: {key}')
            names.add(symbol(key)); methods.add(method(key))
            if set(row) != {'key', 'notes', 'params', 'platforms', 'status', *ids}:
                fail(f'{key}: unknown or missing fields/translations')
            if set(row['status']) != set(ids): fail(f'{key}: review status locales disagree')
            if not row['notes'].strip() or not row['platforms'] or set(row['platforms']) - PLATFORMS or len(set(row['platforms'])) != len(row['platforms']):
                fail(f'{key}: notes/platforms required')
            for name, spec in row['params'].items():
                if not re.fullmatch('[a-z][a-zA-Z0-9]*', name) or name in set('locale context message args class when type func var let repeat switch case default in for if else return map range string int double nil null true false object val fun enum struct import package public private internal select defer go interface protocol self super any async await throws throw try catch do while break continue guard as is extension'.split()) or set(spec) != {'type', 'example'} or spec['type'] not in TYPES:
                    fail(f'{key}: invalid parameter {name}')
                example = spec['example']
                if (spec['type'] == 'string' and not isinstance(example, str) or
                    spec['type'] == 'integer' and type(example) is not int or
                    spec['type'] == 'number' and type(example) not in (int, float)):
                    fail(f'{key}: bad example for {name}')
            signature = None
            for loc in locales['locales']:
                lang = loc['id']; value = row[lang]
                status = row['status'].get(lang)
                if status not in {'source', 'draft', 'reviewed'} or (lang != locales['source'] and status == 'source') or (lang == locales['source'] and status == 'draft'):
                    fail(f'{key}: invalid review status')
                if locales['selectionEnabled'] and status not in {'source', 'reviewed'}:
                    fail(f'{key}: {lang} is not reviewed')
                if isinstance(value, dict):
                    kind = 'plural' if 'plural' in value else 'select'
                    if set(value) != {kind, 'forms'} or value[kind] not in row['params'] or not isinstance(value['forms'], dict) or 'other' not in value['forms']:
                        fail(f'{key}: malformed selector')
                    if kind == 'plural' and (row['params'][value[kind]]['type'] != 'integer' or set(value['forms']) != set(loc['plural'])):
                        fail(f'{key}: plural parameter/categories disagree')
                    if kind == 'select' and (row['params'][value[kind]]['type'] != 'string' or any(not re.fullmatch('[a-z][a-z0-9_]*', f) for f in value['forms'])):
                        fail(f'{key}: invalid select')
                    sig = (kind, value[kind], tuple(sorted(value['forms'])) if kind == 'select' else None)
                elif isinstance(value, str):
                    sig = ('text',)
                else:
                    fail(f'{key}: invalid message')
                if signature is not None and sig != signature:
                    fail(f'{key}: selector differs by locale')
                signature = sig
                for text in leaves(value):
                    if not isinstance(text, str) or not text.strip():
                        fail(f'{key}: empty translation')
                    refs = set(PARAM.findall(text))
                    # A select chooses a branch; it need not appear in the visible text.
                    required = set(row['params']) - ({value['select']} if isinstance(value, dict) and 'select' in value else set())
                    if not required <= refs <= set(row['params']) or re.search('[{}]', PARAM.sub('', text)) or re.search(r'<[^>]+>|%[0-9$]*[sd@fg]', text):
                        fail(f'{key}: parameters/format disagree')
            messages[key] = row
    if not messages:
        fail('no messages')
    # Android flattened select branches and Swift function names share namespaces.
    for platform in ('android', 'ios'):
        for lang in ids:
            occupied = set()
            for key, row in messages.items():
                if platform not in row['platforms']: continue
                for leaf, _ in branches(row, lang):
                    if leaf in occupied: fail(f'platform resource key collision: {leaf}')
                    occupied.add(leaf)
    return locales, dict(sorted(messages.items()))


def native(text, row, apple=False):
    """Positional placeholders allow translators to reorder parameters."""
    names = sorted(row['params'])
    text = text.replace('%', '%%') if apple or row['params'] else text
    def replace(match):
        name = match[1]; typ = row['params'][name]['type']
        spec = TYPES[typ][4] if apple else {'string': 's', 'integer': 'd', 'number': 'f'}[typ]
        return f'%{names.index(name)+1}${spec}'
    return PARAM.sub(replace, text)


def android_text(text):
    # Quoting also preserves whitespace and stops Android treating @/? as references.
    text = text.replace('\\', '\\\\').replace('"', '\\"').replace("'", "\\'").replace('\n', '\\n').replace('\t', '\\t')
    return '"' + escape(text) + '"'


def branches(row, lang):
    value = row[lang]
    if isinstance(value, str):
        return [(symbol(row['key']), value)]
    if 'select' in value:
        return [(symbol(row['key']) + '_' + k, v) for k, v in sorted(value['forms'].items())]
    return [(symbol(row['key']), value)]


def build(root):
    locales, messages = load(root)
    out = {}
    def put(path, text):
        out[path] = text
    def template(name):
        return (ROOT / 'scripts/i18n_templates' / name).read_text(encoding='utf-8')
    metadata = {l['id']: l for l in locales['locales']}
    ts = f'// {HEADER}\nexport const localeData = {dump(locales).strip()} as const;\n'
    ts += 'export type Locale = typeof localeData.locales[number]["id"];\nexport interface MessageArgs {\n'
    for key, row in messages.items():
        if 'web' in row['platforms']:
            fields = '; '.join(f'{n}: {TYPES[p["type"]][0]}' for n,p in sorted(row['params'].items())) or '[name: string]: never'
            ts += f'  "{key}": {{ {fields} }};\n'
    ts += '}\nexport type MessageKey = keyof MessageArgs;\nexport const messages = '+dump({l:{k:r[l] for k,r in messages.items() if 'web' in r['platforms']} for l in metadata}).strip()+' as const;\n'
    put('web/src/i18n/generated.ts', ts)
    put('web/src/i18n/locale-vectors.json', dump(read(root / 'i18n/locale-vectors.json')))

    pkg = 'io.github.lewin671.remoteagent'
    core = f'// {HEADER}\npackage {pkg}.core\n\n'
    core += 'class UiMessage internal constructor(val key: String, val args: Map<String, Any> = emptyMap())\n\nobject UiMessages {\n'
    app = f'// {HEADER}\npackage {pkg}.ui\n\nimport android.content.Context\nimport android.content.res.Configuration\nimport {pkg}.R\nimport {pkg}.core.UiMessage\nimport {pkg}.core.MessageLocale\n\n'
    app += 'fun resolveUiMessage(context: Context, message: UiMessage, locale: String = "zh-CN"): String {\n    val language = MessageLocale.resolve(locale, emptyList())\n    val configuration = Configuration(context.resources.configuration)\n    configuration.setLocale(java.util.Locale.forLanguageTag(MessageLocale.appleTags.getValue(language)))\n    val resources = context.createConfigurationContext(configuration).resources\n    return when (message.key) {\n'
    swift = f'// {HEADER}\nimport Foundation\n\npublic enum L10n {{\n'
    swift += template('swift-runtime.txt')
    go = '// '+HEADER+'\npackage i18n\n\nimport (\n\t"embed"\n\t"encoding/json"\n\t"fmt"\n\t"regexp"\n\t"strconv"\n\t"strings"\n)\n\n'
    go += template('go-runtime.txt')
    catalog = {'sourceLanguage': locales['source'], 'version':'1.0', 'strings':{}}
    strings = {lang:[] for lang in metadata}; dicts = {lang:{} for lang in metadata}
    for key, row in messages.items():
        fn = method(key); params = sorted(row['params']); value = row[locales['source']]
        kind = 'plural' if isinstance(value, dict) and 'plural' in value else 'select' if isinstance(value, dict) else 'text'
        if 'android' in row['platforms']:
            arguments = ', '.join(f'{n}: {TYPES[row["params"][n]["type"]][1]}' for n in params)
            argmap = 'mapOf('+', '.join(f'"{n}" to {n}' for n in params)+')' if params else 'emptyMap()'
            core += f'    fun {fn}({arguments}): UiMessage = UiMessage("{key}", {argmap})\n'
            app += f'        "{key}" -> {{\n'
            for n in params:
                app += f'            val {n} = message.args.getValue("{n}") as {TYPES[row["params"][n]["type"]][1]}\n'
            suffix = (', '+', '.join(params)) if params else ''
            if kind == 'select':
                app += f'            val id = when ({value["select"]}) {{\n'
                for form in sorted(value['forms']):
                    if form != 'other': app += f'                "{form}" -> R.string.{symbol(key)}_{form}\n'
                app += f'                else -> R.string.{symbol(key)}_other\n            }}\n            resources.getString(id{suffix})\n'
            elif kind == 'plural':
                app += f'            resources.getQuantityString(R.plurals.{symbol(key)}, {value["plural"]}{suffix})\n'
            else:
                app += f'            resources.getString(R.string.{symbol(key)}{suffix})\n'
            app += '        }\n'
        if 'ios' in row['platforms']:
            args = ', '.join([f'{n}: {TYPES[row["params"][n]["type"]][2]}' for n in params]+['locale: String = MessageLocale.current'])
            swift += f'    public static func {fn}({args}) -> String {{\n'
            if kind == 'select':
                swift += f'        let key: String\n        switch {value["select"]} {{\n'
                for form in sorted(value['forms']):
                    if form != 'other': swift += f'        case "{form}": key = "{symbol(key)}_{form}"\n'
                swift += f'        default: key = "{symbol(key)}_other"\n        }}\n'
            else: swift += f'        let key = "{symbol(key)}"\n'
            swiftargs = ', '.join(f'Int64({n})' if row['params'][n]['type']=='integer' else n for n in params)
            swift += f'        return format(key, locale: locale, args: [{swiftargs}])\n    }}\n'
        if 'go' in row['platforms']:
            args = ', '.join(['locale string']+[f'{n} {TYPES[row["params"][n]["type"]][3]}' for n in params])
            amap = ', '.join(f'"{n}": {n}' for n in params)
            go += f'\nfunc {fn[0].upper()+fn[1:]}({args}) string {{\n\treturn render(locale, "{key}", map[string]any{{{amap}}})\n}}\n'
        for lang, loc in metadata.items():
            if 'ios' not in row['platforms']: continue
            for leaf, text in branches(row, lang):
                entry = catalog['strings'].setdefault(leaf, {'comment':HEADER+' '+row['notes'],'extractionState':'manual','localizations':{}})
                state = 'translated' if row['status'][lang] in {'source','reviewed'} else 'needs_review'
                if isinstance(text, dict):
                    forms = {f:{'stringUnit':{'state':state,'value':native(t,row,True)}} for f,t in text['forms'].items()}
                    selector = text['plural']; index = params.index(selector)+1
                    entry['localizations'][loc['apple']] = {
                        'stringUnit': {'state': state, 'value': f'%{index}$#@{selector}@'},
                        'substitutions': {selector: {'argNum': index, 'formatSpecifier': 'lld', 'variations': {'plural': forms}}}}
                    dicts[lang][leaf] = {'NSStringLocalizedFormatKey':f'%{index}$#@{selector}@', selector:{'NSStringFormatSpecTypeKey':'NSStringPluralRuleType', 'NSStringFormatValueTypeKey':'lld', **{f:native(t,row,True) for f,t in text['forms'].items()}}}
                else:
                    entry['localizations'][loc['apple']] = {'stringUnit':{'state':state,'value':native(text,row,True)}}
                    strings[lang].append(f'{json.dumps(leaf)} = {json.dumps(native(text,row,True),ensure_ascii=False)};')
    core += '}\n'
    core += template('kotlin-runtime.txt').replace('APPLE_TAGS', ', '.join(f'"{l}" to "{m["apple"]}"' for l,m in metadata.items())).replace('LANGUAGE_MAP', ', '.join(f'"{a}" to "{l}"' for l,m in metadata.items() for a in m['languages']))
    app += '        else -> error("Unknown UI message key")\n    }\n}\n'
    swift += '}\n'
    swift += template('swift-locale.txt').replace('APPLE_TAGS', ', '.join(f'"{l}": "{m["apple"]}"' for l,m in metadata.items())).replace('LANGUAGE_MAP', ', '.join(f'"{a}": "{l}"' for l,m in metadata.items() for a in m['languages']))
    put('android/core/src/main/kotlin/io/github/lewin671/remoteagent/core/UiMessages.generated.kt', core)
    put('android/app/src/main/java/io/github/lewin671/remoteagent/ui/UiMessages.generated.kt', app)
    put('ios/RemoteAgentCore/Sources/RACore/L10n.generated.swift', swift)
    put('ios/RemoteAgentCore/Localization/Localizable.xcstrings', dump(catalog))
    import plistlib
    for lang, loc in metadata.items():
        folder=f'ios/RemoteAgentCore/Sources/RACore/Resources/{loc["apple"]}.lproj'
        put(folder+'/Localizable.strings', '// '+HEADER+'\n'+'\n'.join(strings[lang])+'\n')
        put(folder+'/Localizable.stringsdict', plistlib.dumps(dicts[lang],sort_keys=True).decode())
        xml=['<?xml version="1.0" encoding="utf-8"?>', '<!-- '+HEADER+' -->','<resources>']
        for key,row in messages.items():
            if 'android' not in row['platforms']: continue
            for leaf,text in branches(row,lang):
                if isinstance(text,dict):
                    xml.append(f'    <plurals name="{leaf}">')
                    for form,t in sorted(text['forms'].items()):
                        xml.append(f'        <item quantity="{form}">{android_text(native(t,row))}</item>')
                    xml.append('    </plurals>')
                else: xml.append(f'    <string name="{leaf}"'+(' formatted="false"' if not row['params'] else '')+f'>{android_text(native(text,row))}</string>')
        xml.append('</resources>')
        put(f'android/app/src/main/res/values-{loc["android"]}/i18n.xml','\n'.join(xml)+'\n')
        if lang == locales['default']: put('android/app/src/main/res/values/i18n.xml','\n'.join(xml)+'\n')
    put('internal/i18n/messages.generated.go', go)
    put('internal/i18n/messages.generated.json', dump({'locales':locales,'messages':{k:r for k,r in messages.items() if 'go' in r['platforms']}}))
    return out


def generate(root, check=False):
    output = build(root)
    if output != build(root):
        fail('non-deterministic generation')
    # A manifest catches obsolete files as well as missing/stale current files.
    manifest = 'i18n/generated-files.json'
    previous = read(root / manifest) if (root / manifest).exists() else []
    output[manifest] = dump(sorted(output))
    if check:
        with tempfile.TemporaryDirectory(prefix='ra-i18n-') as tmp:
            for name,text in output.items():
                target=Path(tmp)/name; target.parent.mkdir(parents=True,exist_ok=True);target.write_text(text, encoding="utf-8", newline="\n")
            stale=[n for n,t in output.items() if not (root/n).exists() or (root/n).read_bytes() != (Path(tmp)/n).read_bytes()]
        stale += [n for n in previous if n not in output and (root/n).exists()]
        if stale: fail('stale generated files (run generate): '+', '.join(stale))
    else:
        for name in previous:
            if name not in output and (root/name).exists(): (root/name).unlink()
        for name,text in output.items():
            path=root/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text, encoding="utf-8", newline="\n")


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('command',choices=['generate','lint'])
    parser.add_argument('--check',action='store_true')
    parser.add_argument('--update-baseline',action='store_true')
    args=parser.parse_args()
    try:
        if args.command=='generate':
            generate(ROOT,args.check)
            if args.check:
                from i18n_lint import references
                references(ROOT)
        else:
            # Kept separate so the compiler can be imported by tests without scanning.
            from i18n_lint import lint
            lint(ROOT,args.update_baseline)
    except (ValueError, KeyError, TypeError) as error:
        parser.exit(1,f'i18n: {error}\n')

if __name__=='__main__': main()
